module dsu (\n  input clk, rst_n, start,\n  input op_type,\n  input [2:0] a, b,\n  output reg done,\n  output reg result\n);\n\n  // State definitions\n  localparam [2:0] IDLE         = 3'd0;\n  localparam [2:0] FIND_A_READ  = 3'd1;\n  localparam [2:0] FIND_A_CHECK = 3'd2;\n  localparam [2:0] FIND_B_READ  = 3'd3;\n  localparam [2:0] FIND_B_CHECK = 3'd4;\n  localparam [2:0] UNION        = 3'd5;\n  localparam [2:0] QUERY        = 3'd6;\n  localparam [2:0] DONE_STATE   = 3'd7;\n\n  // Registers\n  reg [2:0] state, next_state;\n  reg [2:0] curr_a, curr_b;\n  reg [2:0] root_a, root_b;\n  reg [2:0] parent_a, parent_b;\n  reg op_type_reg;\n  reg [2:0] a_reg, b_reg;\n  reg [2:0] parent [0:7];\n  reg [1:0] rank [0:7];\n  reg [2:0] i; // Loop counter\n\n  // Combinational logic\n  always @(*) begin\n    next_state = state;\n    case (state)\n      IDLE: begin\n        if (start) next_state = FIND_A_READ;\n      end\n      FIND_A_READ: next_state = FIND_A_CHECK;\n      FIND_A_CHECK: begin\n        if (parent_a == curr_a) next_state = FIND_B_READ;\n        else next_state = FIND_A_READ;\n      end\n      FIND_B_READ: next_state = FIND_B_CHECK;\n      FIND_B_CHECK: begin\n        if (parent_b == curr_b) begin\n          if (op_type_reg == 1'b1) next_state = QUERY;\n          else next_state = UNION;\n        end else next_state = FIND_B_READ;\n      end\n      UNION: next_state = DONE_STATE;\n      QUERY: next_state = DONE_STATE;\n      DONE_STATE: next_state = IDLE;\n      default: next_state = IDLE;\n    endcase\n  end\n\n  // Sequential logic\n  always @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n      // Initialize all registers and arrays\n      for (i = 0; i < 8; i = i + 1) begin\n        parent[i] <= i;\n        rank[i] <= 2'd0;\n      end\n      state <= IDLE;\n      done <= 1'b0;\n      result <= 1'b0;\n      curr_a <= 3'd0;\n      curr_b <= 3'd0;\n      root_a <= 3'd0;\n      root_b <= 3'd0;\n      parent_a <= 3'd0;\n      parent_b <= 3'd0;\n      op_type_reg <= 1'b0;\n      a_reg <= 3'd0;\n      b_reg <= 3'd0;\n    end else begin\n      state <= next_state;\n      case (state)\n        IDLE: begin\n          done <= 1'b0;\n          if (start) begin\n            op_type_reg <= op_type;\n            a_reg <= a;\n            b_reg <= b;\n            curr_a <= a;\n            curr_b <= b;\n          end\n        end\n\n        FIND_A_READ: begin\n          parent_a <= parent[curr_a];\n        end\n\n        FIND_A_CHECK: begin\n          if (parent_a == curr_a) begin\n            root_a <= curr_a;\n            curr_b <= b_reg;\n          end else begin\n            curr_a <= parent_a;\n          end\n        end\n\n        FIND_B_READ: begin\n          parent_b <= parent[curr_b];\n        end\n\n        FIND_B_CHECK: begin\n          if (parent_b == curr_b) begin\n            root_b <= curr_b;\n          end else begin\n            curr_b <= parent_b;\n          end\n        end\n\n        UNION: begin\n          if (root_a != root_b) begin\n            if (rank[root_a] < rank[root_b]) begin\n              parent[root_a] <= root_b;\n            end else if (rank[root_a] > rank[root_b]) begin\n              parent[root_b] <= root_a;\n            end else begin\n              parent[root_b] <= root_a;\n              rank[root_a] <= rank[root_a] + 2'd1;\n            end\n          end\n        end\n\n        QUERY: begin\n          result <= (root_a == root_b) ? 1'b1 : 1'b0;\n        end\n\n        DONE_STATE: begin\n          done <= 1'b1;\n        end\n      endcase\n    end\n  end\nendmodule